script:
test("accepts a document with exactly 30 days left", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-07-01" }), { accepted: true, daysUntilExpiry: 30 });
});
test("rejects a document with 29 days left", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-06-30" }), { accepted: false, daysUntilExpiry: 29 });
});
test("accepts a document with 31 days left", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-07-02" }), { accepted: true, daysUntilExpiry: 31 });
});
test("rejects a document with one day left", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-06-02" }), { accepted: false, daysUntilExpiry: 1 });
});
test("counts 31 days from January 1 to February 1", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-01-01", expiryDate: "2026-02-01" }), { accepted: true, daysUntilExpiry: 31 });
});
test("accepts exactly 30 days from the last day of January across a non-leap February", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-01-31", expiryDate: "2026-03-02" }), { accepted: true, daysUntilExpiry: 30 });
});
test("accepts exactly 30 days from December 2 into January", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-12-02", expiryDate: "2027-01-01" }), { accepted: true, daysUntilExpiry: 30 });
});
test("accepts exactly 30 days from the last day of December", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-12-31", expiryDate: "2027-01-30" }), { accepted: true, daysUntilExpiry: 30 });
});
test("rejects 29 days from December 3 into January", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-12-03", expiryDate: "2027-01-01" }), { accepted: false, daysUntilExpiry: 29 });
});
test("accepts exactly 30 days across a leap-year February", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2024-02-01", expiryDate: "2024-03-02" }), { accepted: true, daysUntilExpiry: 30 });
});
test("rejects 29 days across a non-leap February", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-02-01", expiryDate: "2026-03-02" }), { accepted: false, daysUntilExpiry: 29 });
});
test("accepts exactly 30 days when the expiry date is leap day", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2024-01-30", expiryDate: "2024-02-29" }), { accepted: true, daysUntilExpiry: 30 });
});
test("accepts exactly 30 days when the check date is leap day", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2024-02-29", expiryDate: "2024-03-30" }), { accepted: true, daysUntilExpiry: 30 });
});
test("returns the full day count rather than only the acceptance threshold", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-08-01" }), { accepted: true, daysUntilExpiry: 61 });
});
test("counts 31 days from December 1 into January", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-12-01", expiryDate: "2027-01-01" }), { accepted: true, daysUntilExpiry: 31 });
});
test("throws when the input has an unknown field", function () {
  assert.throws(function () {
    code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-07-01", documentId: "abc" });
  }, /^unknown field: documentId$/);
});
